import{z as c,x as d,o,c as A,q as t,j as n,D as s,d as l,s as E,S as i,b as a}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"seqlock","description":"","frontmatter":{"title":"seqlock","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/seqlock.md","filePath":"cs/seqlock.md","lastUpdated":1791063341000}'),p={name:"cs/seqlock.md"};function q(B,e,m,k,h,u){const r=d("Mermaid");return o(),A("div",null,[e[2]||(e[2]=t('<h1 id="seqlock" tabindex="-1">seqlock <a class="header-anchor" href="#seqlock" aria-label="Permalink to &quot;seqlock&quot;">​</a></h1><div class="epigraph"><p>写者把序列号加奇数再写数据再加成偶数；读者读前后序列，奇数或变化则重试——读侧不持锁。</p><footer>—— 据 Love, Linux Kernel Development；内核文档对 seqlock 的整理</footer></div><p><a href="/cs/rwlock">上一课</a>的读计数仍是共享写，读者多时乒乓，写者还可能饿。时钟、统计一类<strong>写少、数据小、读者可重试</strong>的对象适合另一合同：读者永不挡写者。缺口是 <strong>seqlock</strong>（顺序锁）：版本号 + 写者互斥，读者无锁采样。本课钉重试协议，不把 RCU 宽限期写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>读者若只读一个字，原子加载够。读者若读两个相关字段，普通加载可撕裂。seqlock：写者获取内部自旋（或 mutex），<code>seq++</code> 成奇，写字段，<code>seq++</code> 成偶。读者：读 seq 为偶，读字段，再读 seq；若不同或为奇，重试。缺口不是 rwlock 的兼容矩阵，而是<strong>写优先、读可失败重来</strong>。</p><p><span class="marginnote">读者临界区不能有副作用：因为可能重试多次。也不能在读侧睡眠指望一致性，除非改用别的原语。</span></p><p><span class="marginnote">数字实例：时钟计数对象 seq 从 4 开始。写者把 seq 改成 5（奇数，正在写）再改成 6（偶数，写完）。读者第一次读到 4、第二次读到 6——说明中间过了一轮写入，这次采样作废重来；第一次就读到 5 说明正撞上写入，同样重来。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写者之间仍互斥，保证 seq 与数据配对。读者用 acquire 语义读 seq，防止把数据读提前到第一次 seq 之前——对接<a href="/cs/memory-barrier-os">内存屏障</a>。写很频繁时读者会活锁式重试，于是不适合写多的对象。</p>',9)),(o(),n(i,null,{default:s(()=>[E(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E5%86%99%3A%20seq%20%E5%A5%87%20%E2%86%92%20%E6%94%B9%E6%95%B0%E6%8D%AE%20%E2%86%92%20seq%20%E5%81%B6%22%5D%20--%3E%20R%5B%22%E8%AF%BB%3A%20%E5%81%B6%E4%B8%94%E4%B8%A4%E6%AC%A1%20seq%20%E7%9B%B8%E5%90%8C%E6%89%8D%E6%8E%A5%E5%8F%97%22%5D%0A%20%20R%20--%3E%20RETRY%5B%22%E5%90%A6%E5%88%99%E9%87%8D%E8%AF%95%22%5D%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=a("p",null,"IRQ 里可以读 seqlock；写者若也在 IRQ，要按锁与 IRQ 纪律选自旋变体。",-1)),e[4]||(e[4]=a("h2",{id:"机制",tabindex:"-1"},[l("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[5]||(e[5]=a("p",null,"seqlock 把一致性从「锁内看见」换成「采样到偶数版本」。它消灭读侧锁字写入，写者不会被读者挡。读者无所有者、无 PI。与后课 RCU 不同：seqlock 读者可能看见撕过的中间态并扔掉，RCU 读者看见的是完整旧版或完整新版。本课只预告，不展开宽限期。",-1)),e[6]||(e[6]=a("p",null,"上面那张图是写读两侧的合同总览；下面这张把读者侧的重试循环展开——什么时候才算「采到一份完整样本」。",-1)),(o(),n(i,null,{default:s(()=>[E(r,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E8%AF%BB%E7%AC%AC%E4%B8%80%E6%AC%A1%20seq%22%5D%20--%3E%20B%7B%22%E6%98%AF%E5%81%B6%E6%95%B0%3F%22%7D%0A%20%20B%20--%20%22%E5%90%A6%22%20--%3E%20A%0A%20%20B%20--%20%22%E6%98%AF%22%20--%3E%20C%5B%22%E8%AF%BB%E6%95%B0%E6%8D%AE%E5%AD%97%E6%AE%B5%22%5D%0A%20%20C%20--%3E%20D%5B%22acquire%20%E8%AF%BB%E7%AC%AC%E4%BA%8C%E6%AC%A1%20seq%22%5D%0A%20%20D%20--%3E%20E%7B%22%E4%B8%A4%E6%AC%A1%E7%9B%B8%E5%90%8C%3F%22%7D%0A%20%20E%20--%20%22%E5%90%A6%22%20--%3E%20A%0A%20%20E%20--%20%22%E6%98%AF%22%20--%3E%20F%5B%22%E6%8E%A5%E5%8F%97%E8%BF%99%E4%BB%BD%E6%95%B0%E6%8D%AE%22%5D%0A"})]),fallback:s(()=>[...e[1]||(e[1]=[l(" Loading... ",-1)])]),_:1})),e[7]||(e[7]=t('<p><span class="marginnote">直觉类比：seqlock 读者像在告示板前拍照——拍完核对角上的版本号，若号变了说明刚才有人在换告示，照片作废再拍一张。换告示的人从不停下来等拍照的人，只由写者之间排队。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 <code>seqcount</code> 与 latch 的全部变体写完。也不能用 seqlock 保护链式结构的遍历（中间结点可能被释放）——那是 RCU 或锁。信号量下一课在已有课里；按树，seqlock 之后是<a href="/cs/semaphore">信号量</a>。</p><p><span class="marginnote">常见误区：以为 seqlock 能顺带保护指针遍历链表。实际上读者可能撞上「结点刚被释放」的中间态，重试也救不回已释放的内存——保护指针结构要用锁或 RCU，seqlock 只适合几个字段的定长值对象。</span></p><p>后课默认：小数据、写少、读可重试用 seqlock。计数与条件等待回到 Dijkstra 的 P/V，下一课<a href="/cs/semaphore">信号量</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>seqlock：写者改版本号，读者校验两次序列；读不挡写。</li><li>读者必须可重试、无副作用；写多会让读者空转。</li><li>计数式等待是信号量课。</li><li>出处：Love, <em>LKD</em>。</li></ul>',7))])}const C=c(p,[["render",q]]);export{f as __pageData,C as default};
